import { Group, Mesh, PlaneGeometry, RingGeometry, BoxGeometry, LineSegments, EdgesGeometry, Color } from 'three';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, NodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export interface NodeConfig {
  imageUrl?: string;
  depthMapUrl?: string;
  meshUrl?: string;
  intent?: {
    visualSpec?: {
      colors?: {
        background: string;
        surface: string;
        ink: string;
        paper: string;
        accent: string;
        gradientStops: Array<{ at: number; hex: string }>;
      };
      typography?: {
        headline?: any;
        body?: any;
        'cta-label'?: any;
      };
      textContent?: Array<{ text: string; role: string }>;
    };
  };
  textContent?: Array<{ text: string; role: string }>;
  cinematicPrimitives?: Array<{ name: string; params: any; trigger: string }>;
}

export interface NodeContext {
  THREE: any;
  textureLoader: {
    loadTexture(url: string): Promise<any>;
  };
  glbLoader: {
    loadGLB(url: string): Promise<any>;
  };
  fontAtlas: {
    createText(content: string, opts?: {
      fontSize?: number;
      color?: any;
      align?: 'left' | 'center' | 'right';
      maxWidthPx?: number;
      letterSpacingPx?: number;
    }): any;
  };
  primitives: Record<string, (target: any, params: any) => { timeline?: any; cleanup: () => void }>;
  emit: (event: string, payload?: any) => void;
  tier?: 'T0' | 'T1' | 'T2';
}

export default function createNode(config: NodeConfig, ctx: NodeContext): Object3D {
  const root = new Group();

  // Create clean GSAP timelines bank for disposal
  const activeTimelines: gsap.core.Timeline[] = [];

  // Theme Constants
  const colors = config.intent?.visualSpec?.colors ?? {
    background: "#0b0b10",
    surface: "#16161d",
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    gradientStops: [{ at: 0, hex: "#14141a" }, { at: 1, hex: "#0b0b10" }]
  };

  const bgGradStart = new Color(colors.gradientStops[0]?.hex ?? "#14141a");
  const bgGradEnd = new Color(colors.gradientStops[1]?.hex ?? "#0b0b10");
  const paperColor = new Color(colors.paper);
  const strokeColor = new Color("#26262f");

  // --- Stage Backdrop ---
  // A dark backdrop plane at z = -2.5 to avoid a void, wrapping gradients.
  const backdropGeom = new PlaneGeometry(10, 8);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(
    vec3(bgGradStart.r, bgGradStart.g, bgGradStart.b),
    vec3(bgGradEnd.r, bgGradEnd.g, bgGradEnd.b),
    uv().y
  );
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  // --- Main Panel (3.2 x 2.2) ---
  const panelGeom = new PlaneGeometry(3.2, 2.2);
  const panelMat = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.1
  });

  // Engineered radial gradient with hairline grid
  panelMat.colorNode = mix(
    vec3(bgGradStart.r, bgGradStart.g, bgGradStart.b),
    vec3(bgGradEnd.r, bgGradEnd.g, bgGradEnd.b),
    smoothstep(0.0, 1.0, uv().sub(0.5).length().mul(2.0))
  );

  // Hairline grid node logic: continuous grid overlay at 0.25 pitch
  // Base spacing units = 0.25 (scaled from coordinate grid)
  const gridUv = uv().mul(vec3(3.2 / 0.25, 2.2 / 0.25, 1.0));
  const gridLinesX = smoothstep(0.015, 0.0, uv().x.mul(3.2 / 0.25).fract().sub(0.5).abs());
  const gridLinesY = smoothstep(0.015, 0.0, uv().y.mul(2.2 / 0.25).fract().sub(0.5).abs());
  const gridGrid = gridLinesX.add(gridLinesY).clamp(0.0, 1.0);

  panelMat.colorNode = mix(
    panelMat.colorNode,
    vec3(paperColor.r, paperColor.g, paperColor.b),
    gridGrid.mul(0.06) // 6% grid opacity
  );

  const panel = new Mesh(panelGeom, panelMat);
  root.add(panel);

  // Corner radius simulation / outline using wireframe Edges
  const edgeGeo = new EdgesGeometry(panelGeom);
  const hairlineMat = new MeshBasicNodeMaterial({ color: strokeColor });
  const hairlineBorder = new LineSegments(edgeGeo, hairlineMat);
  hairlineBorder.position.z = 0.006;
  panel.add(hairlineBorder);

  // --- Ghost Preview Group (Left of center, x = -0.7) ---
  const ghostGroup = new Group();
  ghostGroup.position.set(-0.7, 0, 0.01);

  // Wireframe watch card outline (1.1w x 1.4h)
  const ghostCardGeom = new PlaneGeometry(1.1, 1.4);
  const ghostEdgeGeo = new EdgesGeometry(ghostCardGeom);
  const ghostWireMat = new MeshBasicNodeMaterial({
    color: paperColor,
    transparent: true,
    opacity: 0.3
  });
  const ghostCardWire = new LineSegments(ghostEdgeGeo, ghostWireMat);
  ghostGroup.add(ghostCardWire);

  // Ghost dial circle (0.55 diameter)
  const dialGeom = new RingGeometry(0.27, 0.275, 48);
  const dialMat = new MeshBasicNodeMaterial({
    color: paperColor,
    transparent: true,
    opacity: 0.22
  });
  const dial = new Mesh(dialGeom, dialMat);
  dial.position.y = 0.2;
  ghostGroup.add(dial);

  // Two ghost text bars (0.7w x 0.06h)
  const barGeom = new PlaneGeometry(0.7, 0.06);
  const barMat = new MeshBasicNodeMaterial({
    color: paperColor,
    transparent: true,
    opacity: 0.22
  });

  const bar1 = new Mesh(barGeom, barMat);
  bar1.position.set(0, -0.25, 0.005);
  ghostGroup.add(bar1);

  const bar2 = new Mesh(barGeom, barMat);
  bar2.position.set(0, -0.4, 0.005);
  ghostGroup.add(bar2);

  panel.add(ghostGroup);

  // Breathe animation for Ghost Preview Group
  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true });
  breatheTl.to(ghostGroup.position, {
    z: 0.02,
    duration: 2.4,
    ease: "power2.inOut"
  });
  // Simulate opacity breathe via children override properties / or standard gsap mesh animation
  const meshesToBreathe = [ghostCardWire, dial, bar1, bar2];
  meshesToBreathe.forEach((m) => {
    breatheTl.to(m.material, {
      opacity: m === ghostCardWire ? 0.34 : 0.26,
      duration: 2.4,
      ease: "power2.inOut"
    }, 0);
  });
  activeTimelines.push(breatheTl);

  // --- Copy Column (Right of center, x = 0.5) ---
  const copyGroup = new Group();
  copyGroup.position.set(0.5, 0.3, 0.01);

  // Text contents
  const headlineItem = config.textContent?.find(t => t.role === 'headline') ?? { text: "Your ledger is empty." };
  const bodyItem = config.textContent?.find(t => t.role === 'body') ?? { text: "Commissioned pieces and saved references will appear here once you begin." };
  const ctaLabelItem = config.textContent?.find(t => t.role === 'cta-label') ?? { text: "BROWSE THE COLLECTION" };

  // Render MSDF text elements safely via context fontAtlas
  const headlineText = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: 24, // maps to suitable local scaling
    color: colors.paper,
    align: 'left',
    maxWidthPx: 500
  });
  // Scale text down to match world unit metric nicely
  headlineText.scale.setScalar(0.008);
  headlineText.position.set(0, 0.1, 0);
  copyGroup.add(headlineText);

  const bodyText = ctx.fontAtlas.createText(bodyItem.text, {
    fontSize: 13,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 420
  });
  bodyText.scale.setScalar(0.008);
  bodyText.position.set(0, -0.22, 0);
  copyGroup.add(bodyText);

  panel.add(copyGroup);

  // --- Accent Action CTA Button (1.5w x 0.36h) ---
  const btnGroup = new Group();
  // Below the body positioning
  btnGroup.position.set(0.85, -0.5, 0.01);

  const btnGeom = new PlaneGeometry(1.5, 0.36);
  const btnMat = new MeshStandardNodeMaterial({
    roughness: 0.1,
    metalness: 0.8,
    emissive: new Color(colors.accent)
  });

  // Emissive and color nodes
  const c_red_start = new Color("#ff4450");
  const c_red_end = new Color("#c1121f");
  btnMat.colorNode = mix(
    vec3(c_red_start.r, c_red_start.g, c_red_start.b),
    vec3(c_red_end.r, c_red_end.g, c_red_end.b),
    uv().y
  );
  // Control edge emissive intensity
  btnMat.emissiveNode = vec3(1.0, 0.16, 0.22).mul(1.5);

  const btnMesh = new Mesh(btnGeom, btnMat);
  btnGroup.add(btnMesh);

  // Ink CTA Text label
  const btnText = ctx.fontAtlas.createText(ctaLabelItem.text, {
    fontSize: 13,
    color: colors.ink,
    align: 'center',
    letterSpacingPx: 1
  });
  btnText.scale.setScalar(0.007);
  btnText.position.set(0, -0.05, 0.01); // Centered relative to button mesh
  btnGroup.add(btnText);

  // Shadow / contact aura under panel bounds
  const shadowGeo = new PlaneGeometry(3.6, 2.6);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.45
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.z = -0.05;
  panel.add(shadowMesh);

  panel.add(btnGroup);

  // --- Interactive Handlers ---
  const onPointerOver = () => {
    gsap.to(btnMesh.scale, { x: 1.03, y: 1.05, z: 1.03, duration: 0.3, ease: "power2.out" });
  };

  const onPointerOut = () => {
    gsap.to(btnMesh.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.3, ease: "power2.out" });
  };

  const onPointerDown = () => {
    gsap.to(btnMesh.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: "back.out(1.7)"
    });
    ctx.emit("navigate", { to: "hub-collection" });
  };

  const onPointerUp = () => {
    gsap.to(btnMesh.scale, {
      x: 1.03,
      y: 1.05,
      duration: 0.12,
      ease: "power2.out"
    });
  };

  // Register interactive capabilities in Node userData
  btnMesh.userData = {
    handlers: {
      pointerover: onPointerOver,
      pointerout: onPointerOut,
      pointerdown: onPointerDown,
      pointerup: onPointerUp
    }
  };

  // --- Entrance Transition (Mount fade-up) ---
  panel.position.y = -0.2;
  panel.scale.setScalar(0.95);
  // Setting up material array or overriding node variables if possible, using GSAP to animate core values
  const entranceTl = gsap.timeline();
  entranceTl.to(panel.position, {
    y: 0.0,
    duration: 0.7,
    ease: "power3.out"
  }).to(panel.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.7,
    ease: "power3.out"
  }, 0);

  activeTimelines.push(entranceTl);

  // Apply Primatives
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const componentInstance = ctx.primitives[prim.name](panel, prim.params);
        if (componentInstance) {
          activeTimelines.push(componentInstance.timeline);
        }
      }
    });
  }

  // Cleanup handler
  root.userData.cleanup = () => {
    activeTimelines.forEach((tl) => {
      if (tl) tl.kill();
    });
    // Recursive disposal
    root.traverse((node: any) => {
      if (node.geometry) {
        node.geometry.dispose();
      }
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach((mat) => mat.dispose());
        } else {
          node.material.dispose();
        }
      }
    });
  };

  return root;
}
